import inspect

def test_dict_merge():
    d1 = {"a": 1, "b": 2}
    d2 = {"b": 99, "c": 3}
    res = merge_configs(d1, d2)
    assert res == {"a": 1, "b": 99, "c": 3}
    src = inspect.getsource(merge_configs)
    assert "|" in src, "Must use PEP 584 dictionary merge operator |"
    assert "update(" not in src, "Avoid mutating with .update()"
